#!/usr/bin/env python3
"""T143: the synthetic ROM images of the Neo Geo benches - generated bytes, no BIOS, no game, nothing of SNK's.

  python3 mkimg.py <out dir> [--z80tone] [--dense [--tile-base N] [--sheet]] [--fix-text STRING]      writes vspace.bin (the machine's ROM space as the DDR2 holds it at rom_base: system ROM at 0, the board fix ROM at 0x20000,
                                                   the cartridge fix ROM S1 at 0x80000, the cartridge program P1 at 0x200000, the sprite ROM at 0x300000, 4 MB), lo.bin (the 64 KB zoom table),
                                                   m1.bin (the Z80 program: NOPs), v1.bin (ADPCM data: silence) and expect.txt (what the benches check)
The "BIOS" at 0xC00000 (system ROM offset 0) is the vector table and a program that sets the palette, the fix layer and kicks the watchdog, then jumps into the cartridge program P1 at
0x000200, which sets up 64 sprites that overlap on many lines (up to 64 per line: the sprite fetch at about two thirds of its limit) and loops forever. The random bytes of the
ROMs come from a fixed generator, so every run (and every memory model) sees the same machine.
"""
import os
import struct
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from m68kasm import Asm  # noqa: E402

VSIZE = 4 * 1024 * 1024
LSPC_ADDR, LSPC_DATA, LSPC_MOD = 0x3C0000, 0x3C0002, 0x3C0004
WDOG = 0x300001
PAL_BASE = 0x400000
BACKDROP_ADDR = PAL_BASE + 0x1FFE
BACKDROP = 0x0F24          # R 15, G 2, B 4, no LSBs, not dark -> RGB565 0xF108 (checked by the bench against the core's own formulas)


def rnd(seed):
    """xorshift32 byte stream"""
    x = seed or 1
    while True:
        x ^= (x << 13) & 0xFFFFFFFF
        x ^= x >> 17
        x ^= (x << 5) & 0xFFFFFFFF
        yield x & 0xFF


def swap16(b):
    """the files of the real machine hold the 68k's words with the bytes swapped (MAME's ROM_LOAD16_WORD_SWAP); the core reads the DDR2 as little endian words"""
    b = bytearray(b)
    if len(b) & 1:
        b.append(0)
    b[0::2], b[1::2] = b[1::2], b[0::2]
    return bytes(b)


def vram_set(a, addr, words):
    a.move_w_imm_abs(addr, LSPC_ADDR)
    for w in words:
        a.move_w_imm_abs(w, LSPC_DATA)


# the Z80 program of the audio bench: SSG channel A at full volume (YM2610 registers 0/1 period, 7 mixer, 8 amplitude through ports 4 and 5), then a loop
Z80_TONE = bytes([0xF3, 0x31, 0xFF, 0xFF,
                  0x3E, 0x00, 0xD3, 0x04, 0x3E, 0x40, 0xD3, 0x05,
                  0x3E, 0x01, 0xD3, 0x04, 0x3E, 0x00, 0xD3, 0x05,
                  0x3E, 0x07, 0xD3, 0x04, 0x3E, 0xFE, 0xD3, 0x05,
                  0x3E, 0x08, 0xD3, 0x04, 0x3E, 0x0F, 0xD3, 0x05,
                  0x18, 0xFE])


def build(outdir, z80tone=False, dense=False, tile_base=0x0200, sheet=False, fix_text=None):
    os.makedirs(outdir, exist_ok=True)
    g = rnd(0x2545F491)
    vs = bytearray(next(g) for _ in range(VSIZE))
    vs[0x80000:0x80000 + 0x20000 * 4] = bytes(0x20000 * 4)          # S1 (fix ROM of the cartridge): transparent...
    for t in range(1, 40):                                           # ...but tiles 1..39: random pixels
        vs[0x80000 + t * 32:0x80000 + (t + 1) * 32] = bytes(next(g) | 0x11 for _ in range(32))
    vs[0x20000:0x40000] = bytes(0x20000)                             # the board fix ROM: transparent
    # ---------------- the "BIOS" (system ROM at 0, seen at 0xC00000): vectors, then the code at 0x100
    bios = bytearray(0x20000)
    struct.pack_into(">II", bios, 0, 0x0010F300, 0x00C00100)          # SSP in work RAM, PC
    for v in range(2, 64):
        struct.pack_into(">I", bios, v * 4, 0x00C00100)               # every other vector: restart (no interrupt is enabled by this program)
    a = Asm(0xC00100)
    a.move_b_imm_abs(0, WDOG)
    a.move_w_imm_abs(1, LSPC_MOD)
    a.move_w_imm_abs(BACKDROP, BACKDROP_ADDR)
    # palette 1 .. 4: 16 colours each, from the generator
    pal = []
    for p in range(1, 5):
        for c in range(16):
            col = (next(g) << 8 | next(g)) & 0x7FFF
            pal.append((PAL_BASE + p * 32 + c * 2, col or 1))
    for ad, col in pal:
        a.move_w_imm_abs(col, ad)
    # fix layer: a short word of tiles at the top left (column-major map at 0x7000 + col * 32 + row)
    for col in range(0 if sheet else 10):                                  # (sheet: no fix tiles, the picture is the sprites and the backdrop only)
        vram_set(a, 0x7000 + (col + 4) * 32 + 3, [0x1000 | (1 + col)])   # palette 1, tiles 1..10
    if fix_text:                                                          # text: the tile number is the character (the layout of the board fix ROM), rows 5 and 7
        for row, line in ((5, fix_text), (7, fix_text.lower())):
            for col, ch in enumerate(line[:36]):
                vram_set(a, 0x7000 + (col + 2) * 32 + row, [0x1000 | ord(ch)])
    a.move_b_imm_abs(0, WDOG)
    a.w(0x4EF9); a.l(0x00000200)                                        # jmp P1+0x200 : the cartridge program
    code = a.bytes()
    bios[0x100:0x100 + len(code)] = code
    vs[0:0x20000] = swap16(bios)
    # ---------------- the cartridge program P1 (virtual 0x200000, 68k address 0): sprites
    p = Asm(0x000200)
    p.move_b_imm_abs(0, WDOG)
    # SCB1: sprite s, tile row t at 0x0000 + s * 64 + t * 2 : tile low word, then attributes (palette, high tile bits, flips)
    if dense:
        # 96 sprites, each 14 tiles tall (the whole picture), all different tiles: every line fetches 96 different sprite lines (the limit of the chip)
        NS = 19 if sheet else 96                                        # sheet: 19 sprites side by side, a window of 19 x 14 consecutive tiles of the C ROM, nothing overlaps
        for s in range(NS):
            vram_set(p, s * 64, [w for t in range(14) for w in (tile_base + s * (16 if sheet else 14) + t, (1 + s % 4) << 8)])
            p.move_b_imm_abs(0, WDOG)
        vram_set(p, 0x8000, [0x0FFF] * NS)                              # SCB2: no shrink
        vram_set(p, 0x8200, [((496 - 16) << 7) | 14 for s in range(NS)])   # SCB3: Y 16, 14 tiles tall
        vram_set(p, 0x8400, [((8 + s * (16 if sheet else 3)) << 7) for s in range(NS)])    # SCB4: X, every 3 pixels (sheet: every 16)
    else:
        NS = 64
        for s in range(NS):
            vram_set(p, s * 64, [0x0100 + (s * 7 % 0x180) * 2, (1 + s % 4) << 8, 0x0101 + (s * 5 % 0x180) * 2, (1 + (s + 1) % 4) << 8])
        p.move_b_imm_abs(0, WDOG)
        vram_set(p, 0x8000, [0x0FFF] * NS)                              # SCB2: no shrink
        vram_set(p, 0x8200, [((496 - (40 + (s * 3) % 48)) << 7) | 2 for s in range(NS)])   # SCB3: Y, two tiles tall
        vram_set(p, 0x8400, [((8 + s * 5) << 7) for s in range(NS)])    # SCB4: X, every 5 pixels
    p.label("loop")
    p.move_b_imm_abs(0, WDOG)
    p.bra("loop")
    pc = p.bytes()
    pcs = swap16(pc)
    vs[0x200000 + 0x200:0x200000 + 0x200 + len(pcs)] = pcs
    open(os.path.join(outdir, "vspace.bin"), "wb").write(bytes(vs))
    g2 = rnd(0x1234567)
    lo = bytearray(next(g2) for _ in range(0x10000))
    if sheet:
        lo[0xFF00:0x10000] = bytes(range(256))                             # the zoom table of a full size sprite (shrink 0xFF): line L of the sprite is tile row L >> 4, line L & 15 of the tile
    open(os.path.join(outdir, "lo.bin"), "wb").write(bytes(lo))
    m1 = bytearray(0x20000)
    if z80tone:
        m1[0:len(Z80_TONE)] = Z80_TONE
    open(os.path.join(outdir, "m1.bin"), "wb").write(bytes(m1))
    open(os.path.join(outdir, "v1.bin"), "wb").write(bytes(0x10000))
    open(os.path.join(outdir, "pal.txt"), "w").write("".join("%d %d %04x\n" % ((ad - PAL_BASE) // 32, (ad - PAL_BASE) % 32 // 2, col) for ad, col in pal) + "backdrop %04x\n" % BACKDROP)
    open(os.path.join(outdir, "pal.txt"), "w").write("".join("%d %d %04x\n" % ((ad - PAL_BASE) // 32, (ad - PAL_BASE) % 32 // 2, col) for ad, col in pal) + "backdrop %04x\n" % BACKDROP)
    open(os.path.join(outdir, "expect.txt"), "w").write("backdrop_word %04x\np1_code_end %06x\n" % (BACKDROP, 0x200000 + 0x200 + len(pc)))
    return len(code), len(pc)


if __name__ == "__main__":
    out = sys.argv[1]
    print("mkimg: BIOS code %d bytes, P1 code %d bytes" % build(out, "--z80tone" in sys.argv, "--dense" in sys.argv, int(sys.argv[sys.argv.index("--tile-base") + 1], 0) if "--tile-base" in sys.argv else 0x0200, "--sheet" in sys.argv, sys.argv[sys.argv.index("--fix-text") + 1] if "--fix-text" in sys.argv else None))
